import React, { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { analyticsService } from '../services/api';
import TiltCard from '../components/TiltCard';

const categories = ['All', 'Performance', 'Content', 'Platform', 'Timing', 'Category', 'Engagement'];

// Badge styling per insight severity (insights are generated by analytics/insights.py)
const SEVERITY_STYLES = {
  positive: {
    badge: 'Strength',
    badgeColor: 'bg-success-container text-on-success-container border-success/20',
    dotColor: 'bg-success',
  },
  neutral: {
    badge: 'Signal',
    badgeColor: 'bg-secondary-container text-on-secondary-container border-secondary/20',
    dotColor: 'bg-secondary',
  },
  warning: {
    badge: 'Needs Attention',
    badgeColor: 'bg-warning-container text-on-warning-container border-warning/20',
    dotColor: 'bg-warning',
  },
};

const PageHeading = ({ children }) => (
  <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4">
    <div>
      <h1 className="font-headline text-headline-lg text-on-surface">Insights</h1>
      <p className="font-body text-body-md text-text-secondary mt-1">Actionable findings from your content data.</p>
    </div>
    {children}
  </div>
);

const StatePanel = ({ icon, title, children }) => (
  <section className="bg-surface border border-outline-variant rounded-lg p-12 text-center flex flex-col items-center gap-3">
    <div className="w-12 h-12 rounded-full bg-surface-elevated border border-outline flex items-center justify-center text-text-muted">
      <span className="material-symbols-outlined text-[24px]">{icon}</span>
    </div>
    <h2 className="font-title text-headline-md text-on-surface">{title}</h2>
    {children}
  </section>
);

const DataActions = () => (
  <div className="flex items-center gap-3 mt-2">
    <Link
      to="/upload"
      className="px-4 py-2 rounded bg-primary text-on-primary font-label text-title-sm font-medium hover:opacity-95"
    >
      Upload CSV
    </Link>
    <Link
      to="/posts"
      className="px-4 py-1.5 rounded bg-surface-elevated border border-outline text-primary font-label text-label-md hover:bg-surface-hover"
    >
      Add Posts
    </Link>
  </div>
);

export default function InsightsPage() {
  const [activeCategory, setActiveCategory] = useState('All');
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchInsights = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      setData(await analyticsService.getInsights());
    } catch (err) {
      setData(null);
      setError(err.status ? err.message : 'Could not reach the SocialIQ server. Check your connection and try again.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchInsights();
  }, [fetchInsights]);

  // ----- Loading State -----
  if (loading) {
    return (
      <main className="flex-1 px-6 py-6 max-w-[1280px] w-full mx-auto flex flex-col gap-6">
        <PageHeading />
        <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4" aria-busy="true">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="bg-surface border border-outline-variant rounded-lg p-5 animate-pulse flex flex-col gap-3">
              <div className="h-3 bg-surface-elevated rounded w-24" />
              <div className="h-5 bg-surface-elevated rounded w-3/4" />
              <div className="h-3 bg-surface-elevated rounded w-full" />
              <div className="h-3 bg-surface-elevated rounded w-2/3" />
            </div>
          ))}
        </section>
      </main>
    );
  }

  // ----- Error State -----
  if (error) {
    return (
      <main className="flex-1 px-6 py-6 max-w-[1280px] w-full mx-auto flex flex-col gap-6">
        <PageHeading />
        <div
          role="alert"
          className="p-4 rounded-lg bg-error-container border border-error/20 text-on-error-container font-body text-body-sm flex items-center justify-between gap-3"
        >
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-[20px]">error</span>
            <span>{error}</span>
          </div>
          <button
            type="button"
            onClick={fetchInsights}
            className="px-3 py-1 rounded bg-surface border border-outline text-on-surface hover:bg-surface-elevated font-label text-label-md"
          >
            Retry
          </button>
        </div>
      </main>
    );
  }

  // ----- Empty State -----
  if (!data || data.status === 'empty') {
    return (
      <main className="flex-1 px-6 py-6 max-w-[1280px] w-full mx-auto flex flex-col gap-6">
        <PageHeading />
        <StatePanel icon="lightbulb" title="No data yet">
          <p className="font-body text-body-sm text-text-secondary max-w-sm">
            Upload a CSV dataset or add posts manually to generate insights from your content.
          </p>
          <DataActions />
        </StatePanel>
      </main>
    );
  }

  // ----- Insufficient-Data State -----
  if (data.status === 'insufficient' || !data.insights?.length) {
    const needMore = data.totalPosts < data.minPosts;
    return (
      <main className="flex-1 px-6 py-6 max-w-[1280px] w-full mx-auto flex flex-col gap-6">
        <PageHeading />
        <StatePanel icon="query_stats" title="Not enough data for reliable insights">
          <p className="font-body text-body-sm text-text-secondary max-w-md">
            {needMore
              ? `You have ${data.totalPosts} post${data.totalPosts === 1 ? '' : 's'}. Insights need at least ${data.minPosts} posts so a single post doesn't drive a conclusion.`
              : `Your ${data.totalPosts} posts don't yet have enough posts per content type, platform, category or day to compare them reliably. Add more posts across different groups.`}
          </p>
          <DataActions />
        </StatePanel>
      </main>
    );
  }

  // ----- Success State -----
  const insights = data.insights;
  const filteredInsights =
    activeCategory === 'All' ? insights : insights.filter((item) => item.category === activeCategory);

  return (
    <main className="flex-1 px-6 py-6 max-w-[1280px] w-full mx-auto flex flex-col gap-6">
      {/* Page Heading & Tabs */}
      <PageHeading>
        {/* Filter Tabs */}
        <div className="flex flex-wrap items-center gap-1.5 p-1 rounded bg-surface border border-outline-variant self-start">
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              onClick={() => setActiveCategory(cat)}
              className={`px-3 py-1 rounded-sm font-label text-label-md transition-colors ${
                activeCategory === cat
                  ? 'bg-surface-elevated text-primary shadow-sm'
                  : 'text-text-secondary hover:text-on-surface'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </PageHeading>

      {/* Cards Grid */}
      {filteredInsights.length === 0 ? (
        <p className="font-body text-body-sm text-text-secondary">
          No {activeCategory.toLowerCase()} insights could be drawn from your current data.
        </p>
      ) : (
        <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 items-stretch">
          {filteredInsights.map((insight) => {
            const style = SEVERITY_STYLES[insight.severity] || SEVERITY_STYLES.neutral;
            return (
              <TiltCard
                key={insight.id}
                className="bg-surface border border-outline-variant rounded-lg p-5 flex flex-col justify-between gap-4 hover:border-outline"
              >
                <div className="flex flex-col gap-2.5">
                  <div className="flex items-center justify-between">
                    <span className="font-label text-label-md uppercase tracking-wider text-text-secondary">
                      {insight.category}
                    </span>
                    <span
                      className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full font-label text-label-md border ${style.badgeColor}`}
                    >
                      {style.badge}
                    </span>
                  </div>
                  <h2 className="font-title text-headline-md text-on-surface leading-snug">{insight.title}</h2>
                  <p className="font-body text-body-sm text-text-secondary leading-relaxed">{insight.description}</p>
                  {insight.comparison && (
                    <p className="font-mono text-mono-sm text-text-muted">{insight.comparison}</p>
                  )}
                </div>

                <div className="pt-3 border-t border-outline-variant flex items-center justify-between gap-3">
                  <span className="font-mono text-mono-sm text-primary tabular-nums font-medium">
                    {insight.value} {insight.metric}
                  </span>
                  <div className="flex items-center gap-1.5 shrink-0" title="Number of posts this insight is based on">
                    <span className={`w-2 h-2 rounded-full ${style.dotColor}`}></span>
                    <span className="font-mono text-mono-sm text-text-muted">n = {insight.sampleSize}</span>
                  </div>
                </div>
              </TiltCard>
            );
          })}
        </section>
      )}
    </main>
  );
}
